// src/components/Contact.js

import React, { useState } from 'react';
import axios from 'axios'; // Import Axios for making HTTP requests
import 'bootstrap/dist/css/bootstrap.min.css';
import '../styles/contact.css';
import { motion } from 'framer-motion';
import DOMPurify from 'dompurify'; // Import DOMPurify for sanitization

const Contact = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    message: ''
  });
  const [formError, setFormError] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.id]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Sanitize message using DOMPurify
    const sanitizedMessage = DOMPurify.sanitize(formData.message);

    try {
      const response = await axios.post('/api/contact', {
        ...formData,
        message: sanitizedMessage // Use sanitized message in the request
      });
      console.log(response.data);
      setFormData({
        fullName: '',
        email: '',
        message: ''
      });
      alert('Message sent successfully!');
    } catch (error) {
      console.error('Error sending message:', error);
      if (error.response) {
        // The request was made and the server responded with a status code
        // that falls out of the range of 2xx
        setFormError(`Server responded with ${error.response.status} error.`);
      } else if (error.request) {
        // The request was made but no response was received
        setFormError('No response received from server. Please try again later.');
      } else {
        // Something happened in setting up the request that triggered an Error
        setFormError('Error setting up the request. Please try again later.');
      }
    }
  };

  return (
    <motion.div
      className="container py-5"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      transition={{ duration: 0.5 }}
    >
      <div className="card border-0 shadow">
        <div className="card-body">
          <h2 className="card-title mb-4">Contact Us</h2>
          {formError && <div className="alert alert-danger">{formError}</div>}
          <form onSubmit={handleSubmit}>
            <div className="mb-3">
              <label htmlFor="fullName" className="form-label">Full Name</label>
              <input type="text" className="form-control" id="fullName" value={formData.fullName} onChange={handleChange} required />
            </div>
            <div className="mb-3">
              <label htmlFor="email" className="form-label">Email address</label>
              <input type="email" className="form-control" id="email" value={formData.email} onChange={handleChange} required />
            </div>
            <div className="mb-3">
              <label htmlFor="message" className="form-label">Message</label>
              <textarea className="form-control" id="message" rows="5" value={formData.message} onChange={handleChange} required></textarea>
            </div>
            <button type="submit" className="btn btn-primary">Submit</button>
          </form>
        </div>
      </div>
    </motion.div>
  );
};

export default Contact;
